  ($q$t01$q$, $q$travel$q$, 0, $q$Where are you going? Bangkok, Phuket$q$, $j$[{"id":"wi-1","type":"wordIntro","word":{"thai":"ไป","roman":"pai","english":"go"},"source":"Essential Thai (Higbie), p.33"},{"id":"wi-2","type":"wordIntro","word":{"thai":"ไหน","roman":"nǎi","english":"where"},"source":"Essential Thai (Higbie), p.33"},{"id":"mc-157","type":"translationChoice","thai":"ไปไหน","roman":"pai nǎi","options":[{"text":"I'm going out.","correct":false},{"text":"Where are you going?","correct":true},{"text":"I'm going to Bangkok.","correct":false},{"text":"I'm going to Phuket.","correct":false}],"source":"Essential Thai (Higbie), p.33","parts":["ไป","ไหน"]},{"id":"sp-162","type":"speak","thai":"ไปไหน","roman":"pai nǎi","meaning":"Where are you going?","source":"Essential Thai (Higbie), p.33","parts":["ไป","ไหน"]},{"id":"wi-4","type":"wordIntro","word":{"thai":"เที่ยว","roman":"thîao","english":"go out / travel around"},"source":"Essential Thai (Higbie), p.33"},{"id":"so-158","type":"sentenceOrder","prompt":"I'm going out. (said by a man)","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"thîao","thai":"เที่ยว"},"x0":{"thai":"ไหน","roman":"nǎi"},"subj":{"thai":"ผม","roman":"phǒm"}},"poolOrder":["b","subj","a","x0"],"correctOrder":["subj","a","b"],"source":"Essential Thai (Higbie), p.33"},{"id":"wi-8","type":"wordIntro","word":{"thai":"กรุงเทพฯ","roman":"grung-thêep","english":"Bangkok"},"source":"Essential Thai (Higbie), p.33"},{"id":"mc-159","type":"translationChoice","thai":"ฉันไปกรุงเทพฯ","roman":"chán pai grung-thêep","options":[{"text":"I'm going to Bangkok.","correct":true},{"text":"I'm going out.","correct":false},{"text":"Where are you going?","correct":false},{"text":"I'm going to Phuket.","correct":false}],"source":"Essential Thai (Higbie), p.33","parts":["ฉัน","ไป","กรุงเทพฯ"]},{"id":"wi-9","type":"wordIntro","word":{"thai":"ภูเก็ต","roman":"phuu-gèt","english":"Phuket"},"source":"Essential Thai (Higbie), p.33"},{"id":"sp-160","type":"speak","thai":"ผมไปภูเก็ต","roman":"phǒm pai phuu-gèt","meaning":"I'm going to Phuket.","source":"Essential Thai (Higbie), p.33","parts":["ผม","ไป","ภูเก็ต"]},{"id":"so-161","type":"sentenceOrder","prompt":"I'm going on a trip to Phuket. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"thîao","thai":"เที่ยว"},"c":{"roman":"phuu-gèt","thai":"ภูเก็ต"},"x0":{"thai":"กรุงเทพฯ","roman":"grung-thêep"},"x1":{"thai":"ไหน","roman":"nǎi"},"subj":{"thai":"ฉัน","roman":"chán"}},"poolOrder":["c","b","a","subj","x0","x1"],"correctOrder":["subj","a","b","c"],"source":"Essential Thai (Higbie), p.33"},{"id":"rp-163","type":"reply","context":[{"speaker":"M","thai":"ไปไหน","parts":["ไป","ไหน"],"roman":"pai nǎi","english":"Where are you going?"}],"replySpeaker":"F","thai":"ฉันไปภูเก็ต","roman":"chán pai phuu-gèt","english":"I'm going to Phuket.","options":[{"thai":"ไปไหน","roman":"pai nǎi","correct":false},{"thai":"เที่ยว","roman":"thîao","correct":false},{"thai":"ฉันไปภูเก็ต","roman":"chán pai phuu-gèt","correct":true}],"source":"Essential Thai (Higbie), p.33","parts":["ฉัน","ไป","ภูเก็ต"]},{"id":"match-164","type":"match","pairs":[{"thai":"ไป","roman":"pai","english":"go"},{"thai":"ไหน","roman":"nǎi","english":"where"},{"thai":"เที่ยว","roman":"thîao","english":"go out / travel around"},{"thai":"กรุงเทพฯ","roman":"grung-thêep","english":"Bangkok"},{"thai":"ภูเก็ต","roman":"phuu-gèt","english":"Phuket"}],"source":"Essential Thai (Higbie), p.33"}]$j$::jsonb),
  ($q$t02$q$, $q$travel$q$, 1, $q$How are you going? Bus, train, taxi$q$, $j$[{"id":"rule-15","type":"rule","title":"\"By\" isn't needed","body":"Thai doesn't use a word for \"by\" — \"I'm going by bus\" is just \"go-bus\" (pai + the vehicle name), with nothing in between.","source":"Essential Thai (Higbie), p.34"},{"id":"wi-16","type":"wordIntro","word":{"thai":"รถเมล์","roman":"rót-mee","english":"bus"},"source":"Essential Thai (Higbie), p.34"},{"id":"mc-165","type":"translationChoice","thai":"ผมไปรถเมล์","roman":"phǒm pai rót-mee","options":[{"text":"I'm going by train.","correct":false},{"text":"I'm going by bus.","correct":true},{"text":"I'm going by tuk-tuk.","correct":false},{"text":"I'm going by taxi.","correct":false}],"source":"Essential Thai (Higbie), p.34","parts":["ผม","ไป","รถเมล์"]},{"id":"sp-170","type":"speak","thai":"ฉันไปรถเมล์","roman":"chán pai rót-mee","meaning":"I'm going by bus.","source":"Essential Thai (Higbie), p.34","parts":["ฉัน","ไป","รถเมล์"]},{"id":"wi-17","type":"wordIntro","word":{"thai":"นั่ง","roman":"nâng","english":"take / ride (a bus, train)"},"source":"Essential Thai (Higbie), p.34"},{"id":"wi-18","type":"wordIntro","word":{"thai":"รถไฟ","roman":"rót-fai","english":"train"},"source":"Essential Thai (Higbie), p.34"},{"id":"so-166","type":"sentenceOrder","prompt":"I'm going by train. (said by a man)","tileUnit":"word","words":{"a":{"roman":"pai","thai":"ไป"},"b":{"roman":"rót-fai","thai":"รถไฟ"},"x0":{"thai":"นั่ง","roman":"nâng"},"x1":{"thai":"ภูเก็ต","roman":"phuu-gèt"},"subj":{"thai":"ผม","roman":"phǒm"}},"poolOrder":["x1","x0","subj","b","a"],"correctOrder":["subj","a","b"],"source":"Essential Thai (Higbie), p.34"},{"id":"so-169","type":"sentenceOrder","prompt":"I'm taking the train to Bangkok. (said by a woman)","tileUnit":"word","words":{"a":{"roman":"nâng","thai":"นั่ง"},"b":{"roman":"rót-fai","thai":"รถไฟ"},"c":{"roman":"pai","thai":"ไป"},"d":{"roman":"grung-thêep","thai":"กรุงเทพฯ"},"x0":{"thai":"ไหน","roman":"nǎi"},"x1":{"thai":"เที่ยว","roman":"thîao"},"subj":{"thai":"ฉัน","roman":"chán"}},"poolOrder":["d","subj","c","b","x0","a","x1"],"correctOrder":["subj","a","b","c","d"],"source":"Essential Thai (Higbie), p.34"},{"id":"wi-23","type":"wordIntro","word":{"thai":"แท็กซี่","roman":"thák-sîi","english":"taxi"},"source":"Essential Thai (Higbie), p.34"},{"id":"mc-167","type":"translationChoice","thai":"ผมไปแท็กซี่","roman":"phǒm pai thák-sîi","options":[{"text":"I'm going by tuk-tuk.","correct":false},{"text":"I'm going by bus.","correct":false},{"text":"I'm going by train.","correct":false},{"text":"I'm going by taxi.","correct":true}],"source":"Essential Thai (Higbie), p.34","parts":["ผม","ไป","แท็กซี่"]},{"id":"wi-24","type":"wordIntro","word":{"thai":"ตุ๊กตุ๊ก","roman":"túk-túk","english":"tuk-tuk (motorized three-wheel taxi)"},"source":"Essential Thai (Higbie), p.136"},{"id":"sp-168","type":"speak","thai":"ฉันไปตุ๊กตุ๊ก","roman":"chán pai túk-túk","meaning":"I'm going by tuk-tuk.","source":"Essential Thai (Higbie), p.34","parts":["ฉัน","ไป","ตุ๊กตุ๊ก"]},{"id":"match-171","type":"match","pairs":[{"thai":"รถเมล์","roman":"rót-mee","english":"bus"},{"thai":"นั่ง","roman":"nâng","english":"take / ride (a bus, train)"},{"thai":"รถไฟ","roman":"rót-fai","english":"train"},{"thai":"แท็กซี่","roman":"thák-sîi","english":"taxi"},{"thai":"ตุ๊กตุ๊ก","roman":"túk-túk","english":"tuk-tuk (motorized three-wheel taxi)"}],"source":"Essential Thai (Higbie), p.34"}]$j$::jsonb),
  ($q$t03$q$, $q$travel$q$, 2, $q$Airplane tickets, station, airport$q$, $j$[{"id":"wi-30","type":"wordIntro","word":{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin","english":"airplane"},"source":"Essential Thai (Higbie), p.136"},{"id":"mc-172","type":"translationChoice","thai":"ผมไปเครื่องบิน","roman":"phǒm pai khrɯ̂ang-bin","options":[{"text":"Where's the airport?","correct":false},{"text":"I'm going by plane.","correct":true},{"text":"one-way","correct":false},{"text":"round trip","correct":false}],"source":"Essential Thai (Higbie), p.136","parts":["ผม","ไป","เครื่องบิน"]},{"id":"sp-177","type":"speak","thai":"ฉันไปเครื่องบิน","roman":"chán pai khrɯ̂ang-bin","meaning":"I'm going by plane.","source":"Essential Thai (Higbie), p.136","parts":["ฉัน","ไป","เครื่องบิน"]},{"id":"wi-32","type":"wordIntro","word":{"thai":"เดียว","roman":"diao","english":"single / only one"},"source":"Essential Thai (Higbie), p.138"},{"id":"so-173","type":"sentenceOrder","prompt":"one-way","tileUnit":"word","words":{"a":{"roman":"thîao","thai":"เที่ยว"},"b":{"roman":"diao","thai":"เดียว"},"x0":{"thai":"ไป","roman":"pai"},"x1":{"thai":"กรุงเทพฯ","roman":"grung-thêep"}},"poolOrder":["x1","x0","a","b"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.136"},{"id":"wi-34","type":"wordIntro","word":{"thai":"กลับ","roman":"glàp","english":"return / go back"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-174","type":"translationChoice","thai":"ไปกลับ","roman":"pai glàp","options":[{"text":"Where's the airport?","correct":false},{"text":"round trip","correct":true},{"text":"one-way","correct":false},{"text":"I'm going by plane.","correct":false}],"source":"Essential Thai (Higbie), p.136","parts":["ไป","กลับ"]},{"id":"wi-37","type":"wordIntro","word":{"thai":"สถานี","roman":"sà-thǎa-nee","english":"station"},"source":"Essential Thai (Higbie), p.137"},{"id":"wi-38","type":"wordIntro","word":{"thai":"สนามบิน","roman":"sà-nǎam-bin","english":"airport"},"source":"Essential Thai (Higbie),