  ($q$t04$q$, $q$travel$q$, 3, $q$Buying tickets, getting on the bus$q$, $j$[{"id":"wi-46","type":"wordIntro","word":{"thai":"เอา","roman":"ao","english":"want / take"},"source":"Essential Thai (Higbie), p.138"},{"id":"wi-47","type":"wordIntro","word":{"thai":"ตั๋ว","roman":"tǔa","english":"ticket"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-180","type":"translationChoice","thai":"เอาตั๋วไปกรุงเทพฯ","roman":"ao tǔa pai grung-thêep","options":[{"text":"two tickets","correct":false},{"text":"How many tickets?","correct":false},{"text":"A ticket to Bangkok, please.","correct":true},{"text":"Where's the bus stop?","correct":false}],"source":"Essential Thai (Higbie), p.138","parts":["เอา","ตั๋ว","ไป","กรุงเทพฯ"]},{"id":"sp-185","type":"speak","thai":"เอาตั๋วไปกรุงเทพฯ","roman":"ao tǔa pai grung-thêep","meaning":"A ticket to Bangkok, please.","source":"Essential Thai (Higbie), p.138","parts":["เอา","ตั๋ว","ไป","กรุงเทพฯ"]},{"id":"wi-49","type":"wordIntro","word":{"thai":"กี่","roman":"gìi","english":"how many?"},"source":"Essential Thai (Higbie), p.138"},{"id":"wi-50","type":"wordIntro","word":{"thai":"ใบ","roman":"bai","english":"classifier for tickets"},"source":"Essential Thai (Higbie), p.138"},{"id":"so-181","type":"sentenceOrder","prompt":"How many tickets?","tileUnit":"word","words":{"a":{"roman":"ao","thai":"เอา"},"b":{"roman":"gìi","thai":"กี่"},"c":{"roman":"bai","thai":"ใบ"},"x0":{"thai":"อยู่","roman":"yùu"},"x1":{"thai":"เครื่องบิน","roman":"khrɯ̂ang-bin"}},"poolOrder":["x1","c","a","b","x0"],"correctOrder":["a","b","c"],"source":"Essential Thai (Higbie), p.138"},{"id":"wi-52","type":"wordIntro","word":{"thai":"สอง","roman":"sɔ̌ɔng","english":"two"},"source":"Essential Thai (Higbie), p.138"},{"id":"mc-182","type":"translationChoice","thai":"สองใบ","roman":"sɔ̌ɔng bai","options":[{"text":"Where's the bus stop?","correct":false},{"text":"two tickets","correct":true},{"text":"A ticket to Bangkok, please.","correct":false},{"text":"How many tickets?","co