  ($q$t08$q$, $q$travel$q$, 7, $q$Turn left, near or far?$q$, $j$[{"id":"rule-107","type":"rule","title":"Near or far?","body":"\"Near\" (glâi) and \"far\" (glai) differ only by tone, which causes confusion — so Thais usually solve the problem by just asking \"is it far?\" and answering \"far\" or \"not far\".","source":"Essential Thai (Higbie), p.148"},{"id":"wi-100","type":"wordIntro","word":{"thai":"ซ้าย","roman":"sáai","english":"left"},"source":"Essential Thai (Higbie), p.147"},{"id":"mc-212","type":"translationChoice","thai":"เลี้ยวซ้าย","roman":"líao sáai","options":[{"text":"Is it far?","correct":false},{"text":"Not far.","correct":false},{"text":"Go straight.","correct":false},{"text":"Turn left.","correct":true}],"source":"Essential Thai (Higbie), p.147","parts":["เลี้ยว","ซ้าย"]},{"id":"sp-217","type":"speak","thai":"เลี้ยวซ้าย","roman":"líao sáai","meaning":"Turn left.","source":"Essential Thai (Higbie), p.147","parts":["เลี้ยว","ซ้าย"]},{"id":"wi-101","type":"wordIntro","word":{"thai":"ตรง","roman":"trong","english":"straight"},"source":"Essential Thai (Higbie), p.147"},{"id":"so-213","type":"sentenceOrder","prompt":"Go straight.","tileUnit":"word","words":{"a":{"roman":"trong","thai":"ตรง"},"b":{"roman":"pai","thai":"ไป"},"x0":{"thai":"เลี้ยว","roman":"líao"},"x1":{"thai":"ซ้าย","roman":"sáai"}},"poolOrder":["a","b","x1","x0"],"correctOrder":["a","b"],"source":"Essential Thai (Higbie), p.147"},{"id":"wi-108","type":"wordIntro","word":{"thai":"ใกล้","roman":"glâi","english":"near"},"source":"Essential Thai (Higbie), p.148"},{"id":"mc-216","type":"translationChoice","thai":"ใกล้","roman":"glâi","options":[{"text":"It's near.","correct":true},{"text":"Is it far?","correct":false},{"text":"Turn left.","correct":false},{"text":"Go straight.","correct":false}],"source":"Essential Thai (Higbie), p.147","parts":["ใกล้"]},{"id":"wi-109","type":"wordIntro","word":{"thai":"ไกล","roman":"glai","english":"far"},"source":"Essential Thai (Higbie), p.148"},{"id":"mc-2