  ($q$t11$q$, $q$travel$q$, 10, $q$In or at? Rice in Thailand and Australia$q$, $j$[{"id":"rule-148","type":"rule","title":"In or at: ที่ and ใน","body":"ที่ (thîi) is the everyday \"in / at\" for a place: อยู่ที่ภูเก็ต — \"(I'm) in Phuket\", ที่เมืองไทย — \"in Thailand\". ใน (nai) means inside something: ในห้อง — \"in the room\".","source":"Requested by the app owner (2026-11-26)"},{"id":"mc-238","type":"translationChoice","thai":"อยู่ที่ภูเก็ต","roman":"yùu thîi phuu-gèt","options":[{"text":"(I'm) in Phuket.","correct":true},{"text":"They grow rice in Thailand.","correct":false},{"text":"in the room","correct":false},{"text":"There are mosquitoes in the room.","correct":false}],"source":"Requested by the app owner (2026-11-26)","parts":["อยู่","ที่","ภูเก็ต"]},{"id":"wi-149","type":"wordIntro","word":{"thai":"ใน","roman":"nai","english":"in / inside"},"source":"Requested by the app owner (2026-11-26)"},{"id":"mc-236","type":"translationChoice","thai":"ในห้อง","roman":"nai hɔ̂ng","options":[{"text":"There are mosquitoes in the room.","correct":false},{"text":"(I'm) in Phuket.","correct":false},{"text":"They grow rice in Thailand.","correct":false},{"text":"in the room","correct":true}],"source":"Requested by the app owner (2026-11-26)","parts":["ใน","ห้อง"]},{"id":"sp-239","type":"speak","thai":"ในห้องมียุง","roman":"nai hɔ̂ng mii yung","meaning":"There are mosquitoes in the room.","source":"Requested by the app owner (2026-11-26)","parts":["ใน","ห้อง","มี","ยุง"]},{"id":"sp-241","type":"speak","thai":"ในห้องไม่มียุง","roman":"nai hɔ̂ng mâi mii yung","meaning":"There are no mosquitoes in the room.","source":"Requested by the app owner (2026-11-26)","parts":["ใน","ห้อง","ไม่","มี","ยุง"]},{"id":"sp-242","type":"speak","thai":"ในห้อง","roman":"nai hɔ̂ng","meaning":"in the room","source":"Requested by the app owner (2026-11-26)","parts":["ใน","ห้อง"]},{"id":"wi-150","type":"wordIntro","word":{"thai":"ข้าว","roman":"khâao","english":"rice"},"source":"Requested by the app owner (2026-11-26)"},{"id":"wi-151","type":"wordIntro","word":{"thai":"ปลูก","roman":"plùuk","english":"grow / plant"},"source":"Requested by the app owner (2026-11-26)"},{"id":"rp-243","type":"reply","context":[{"speaker":"M","thai":"อยู่ที่ไหน","parts":["อยู่","ที่ไหน"],"roman":"yùu thîi-nǎi","english":"Where are you?"}],"replySpeaker":"F","thai":"อยู่ที่กรุงเทพฯ","roman":"yùu thîi grung-thêep","english":"(I'm) in Bangkok.","options":[{"thai":"ปลูกข้าว","roman":"plùuk khâao","correct":false},{"thai":"ในห้องมียุง","roman":"nai hɔ̂ng mii yung","correct":false},{"thai":"อยู่ที่กรุงเทพฯ","roman":"yùu thîi grung-thêep","correct":true}],"source":"Requested by the app owner (2026-11-26)","parts":["อยู่","ที่","กรุงเทพฯ"]},{"id":"wi-152","type":"wordIntro","word":{"thai":"เมืองไทย","roman":"mɯang-thai","english":"Thailand"},"source":"Requested by the app owner (2026-11-26)"},{"id":"so-237","type":"sentenceOrder","prompt":"They grow rice in Thailand.","tileUnit":"word","words":{"a":{"roman":"thîi","thai":"ที่"},"b":{"roman":"mɯang-thai","thai":"เมืองไทย"},"c":{"roman":"plùuk","thai":"ปลูก"},"d":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"กลับ","roman":"glàp"},"x1":{"thai":"แท็กซี่","roman":"thák-sîi"}},"poolOrder":["x0","d","a","x1","b","c"],"correctOrder":["a","b","c","d"],"source":"Requested by the app owner (2026-11-26)"},{"id":"wi-153","type":"wordIntro","word":{"thai":"ออสเตรเลีย","roman":"ɔ́ɔt-sà-tree-lia","english":"Australia"},"source":"Requested by the app owner (2026-11-26)"},{"id":"so-240","type":"sentenceOrder","prompt":"They grow rice in Australia.","tileUnit":"word","words":{"a":{"roman":"thîi","thai":"ที่"},"b":{"roman":"ɔ́ɔt-sà-tree-lia","thai":"ออสเตรเลีย"},"c":{"roman":"plùuk","thai":"ปลูก"},"d":{"roman":"khâao","thai":"ข้าว"},"x0":{"thai":"ขึ้น","roman":"khɯ̂n"},"x1":{"thai":"ขวา","roman":"khwǎa"}},"poolOrder":["c","b","x1","x0","a","d"],"correctOrder":["a","b","c","d"],"source":"Requested by the app owner (2026-11-26)"},{"id":"match-244","type":"ma